const body = ($("Запрос событий").first().json.body) || {};
const allowed = {
  "Personal": "/calendars/YOUR-LOGIN%40yandex.ru/events-0000000/",
  "Family": "/calendars/YOUR-LOGIN%40yandex.ru/events-0000000/",
  "Birthdays": "/calendars/YOUR-LOGIN%40yandex.ru/events-0000000/"
};
const wanted = String(body.calendar || "Personal");
const path = allowed[wanted] || allowed["Personal"];

function stamp(date) {
  const iso = date.toISOString();
  return iso.slice(0, 4) + iso.slice(5, 7) + iso.slice(8, 10) + "T" + iso.slice(11, 13) + iso.slice(14, 16) + iso.slice(17, 19) + "Z";
}

function parseWhen(value, fallback) {
  if (!value) return fallback;
  const text = String(value);
  const full = text.length === 10 && text.charAt(4) === "-" ? text + "T00:00:00Z" : text;
  const date = new Date(full);
  return isNaN(date.getTime()) ? fallback : date;
}

const now = new Date();
const startDefault = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const start = parseWhen(body.from, startDefault);
const end = parseWhen(body.to, new Date(start.getTime() + 30 * 24 * 3600 * 1000));

const query = '<c:calendar-query xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:caldav">'
  + '<d:prop><d:getetag/><c:calendar-data/></d:prop>'
  + '<c:filter><c:comp-filter name="VCALENDAR"><c:comp-filter name="VEVENT">'
  + '<c:time-range start="' + stamp(start) + '" end="' + stamp(end) + '"/>'
  + '</c:comp-filter></c:comp-filter></c:filter></c:calendar-query>';

return [{ json: {
  calendarName: wanted,
  calendarPath: path,
  range: { start: stamp(start), end: stamp(end) },
  query: query
} }];

const prepared = $("Собрать запрос событий").first().json || {};
const xml = String(($json && $json.data) || "");

const events = [];
for (const chunk of xml.split("BEGIN:VEVENT").slice(1)) {
  const item = { summary: "", start: "", end: "", allDay: false, location: "", uid: "" };
  for (let line of chunk.split("END:VEVENT")[0].split("\n")) {
    if (line.length && line.charCodeAt(line.length - 1) === 13) line = line.slice(0, -1);
    const cut = line.indexOf(":");
    if (cut < 0) continue;
    const left = line.slice(0, cut).toUpperCase();
    const value = line.slice(cut + 1).trim();
    if (left.startsWith("SUMMARY")) item.summary = value;
    else if (left.startsWith("DTSTART")) { item.start = value; item.allDay = left.indexOf("VALUE=DATE") >= 0; }
    else if (left.startsWith("DTEND")) item.end = value;
    else if (left.startsWith("LOCATION")) item.location = value;
    else if (left.indexOf("UID") === 0) item.uid = value;
  }
  if (item.summary || item.start) events.push(item);
}

events.sort((left, right) => String(left.start).localeCompare(String(right.start)));

const status = Number(($json && $json.statusCode) || 0);
let note = "ответ получен";
if (status === 401) note = "отказ в доступе — проверить пароль приложения для календаря";
else if (status === 403) note = "календарь отклонил запрос";
else if (status !== 207) note = "код " + status;

return [{ json: {
  calendar: prepared.calendarName,
  range: prepared.range,
  count: events.length,
  status: status,
  note: note,
  events: events.slice(0, 50)
} }];
